from live_evidence.miss_audit import build_miss_audit


def write_row(path: Path, kind: str, payload: dict) -> None:
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps({"kind": kind, "payload": payload}) + "\n")


def test_post_run_audit_classifies_visible_held_superseded_and_missed(tmp_path: Path) -> None:
    journal = tmp_path / "session.jsonl"
    for question_id in ("visible-q", "held-q", "superseded-q", "missed-q"):
        write_row(
            journal,
            "answer_needed_moment",
            {"question_id": question_id, "question_revision": 1},
        )
    write_row(
        journal,
        "card_publication_decision",
        {
            "question_id": "visible-q",
            "question_revision": 1,
            "status": "visible",
            "reason_codes": ["visible_current_question_card"],
            "visible_card_ids": ["card-visible"],
        },
    )
    write_row(
        journal,
        "requirement_ledger_opened",
        {
            "question_id": "held-q",
            "question_revision": 1,
            "entries": [{"blocking": True, "status": "unresolved"}],
        },
    )
    write_row(
        journal,
        "card_publication_decision",
        {
            "question_id": "superseded-q",
            "question_revision": 1,
            "status": "superseded",
            "reason_codes": ["stale_revision_blocked_by_newer_visible_card"],
            "visible_card_ids": [],
        },
    )

    report = build_miss_audit(journal)

    assert report.counts == {"visible": 1, "held": 1, "superseded": 1, "missed": 1}
